insert into public.team_members (id, name, designation, photo_url, bio, linkedin_url, github_url, twitter_url, instagram_url, email, tenure, sort_order) values
  ('a0000000-0000-4000-8000-000000000001', 'Aarav Mehta', 'President', null, 'Final-year CSE. Breaks web apps for fun, writes the fixes for work. Leads club strategy and partnerships.', 'https://www.linkedin.com/', 'https://github.com/', null, 'https://www.instagram.com/', null, '2026–27', 1),
  ('a0000000-0000-4000-8000-000000000002', 'Diya Sharma', 'Vice President', null, 'Cloud security enthusiast and AWS community builder. Keeps every event on schedule.', 'https://www.linkedin.com/', 'https://github.com/', 'https://x.com/', null, null, '2026–27', 2),
  ('a0000000-0000-4000-8000-000000000003', 'Rohan Iyer', 'Technical Lead', null, 'Full-stack developer and maintainer of the club''s open-source projects, including this website.', 'https://www.linkedin.com/', 'https://github.com/', null, null, null, '2026–27', 3),
  ('a0000000-0000-4000-8000-000000000004', 'Kabir Singh', 'CTF & Research Lead', null, 'Reverse engineer and pwn player. Designs the challenges for ISSA CTF every year.', 'https://www.linkedin.com/', 'https://github.com/', null, null, null, '2026–27', 4),
  ('a0000000-0000-4000-8000-000000000005', 'Sneha Kulkarni', 'Events & Outreach Head', null, 'Runs workshops, speaker sessions and the campus cyber-awareness drive.', 'https://www.linkedin.com/', null, null, 'https://www.instagram.com/', null, '2026–27', 5),
  ('a0000000-0000-4000-8000-000000000006', 'Ananya Rao', 'Design & Media Lead', null, 'UI/UX designer behind the ISSA brand. Photographs every event you see in the gallery.', 'https://www.linkedin.com/', null, null, 'https://www.instagram.com/', null, '2026–27', 6),
  ('a0000000-0000-4000-8000-000000000007', 'Vikram Nair', 'AI Security Lead', null, 'Researches adversarial ML and LLM red-teaming. Mentors the PhishNet project.', 'https://www.linkedin.com/', 'https://github.com/', null, null, null, '2026–27', 7),
  ('a0000000-0000-4000-8000-000000000008', 'Meera Joshi', 'Treasurer & Operations', null, 'Manages budgets, sponsorships and logistics so the tech team can focus on building.', 'https://www.linkedin.com/', null, null, null, null, '2026–27', 8)
insert into public.projects (id, title, summary, description, tags, status, repo_url, demo_url, cover_url, contributors, is_featured, sort_order) values
  ('b0000000-0000-4000-8000-000000000001', 'PhishNet', 'Browser extension that flags phishing pages in real time using a lightweight on-device ML model.', 'PhishNet extracts 40+ URL and DOM features and scores pages with a quantised gradient-boosted model that runs entirely in the browser, so no browsing data leaves the device.', array['AI/ML', 'Security', 'Browser']::text[], 'ongoing', 'https://github.com/', null, null, array['Vikram Nair', 'Aarav Mehta']::text[], true, 1),
  ('b0000000-0000-4000-8000-000000000002', 'ISSA CTF Platform', 'Self-hosted capture-the-flag platform with dynamic scoring, team play and 60+ original challenges.', 'Containerised challenge infrastructure with per-team instances, automated flag rotation and a live scoreboard. Powers ISSA CTF every year.', array['Security', 'DevOps', 'CTF']::text[], 'completed', 'https://github.com/', null, null, array['Kabir Singh', 'Rohan Iyer']::text[], true, 2),
  ('b0000000-0000-4000-8000-000000000003', 'Honeypot Lab', 'A network of low-interaction honeypots that logs real-world attacker behaviour for research.', 'SSH, HTTP and SMB honeypots feed an ELK pipeline. Monthly reports summarise attack sources, credentials tried and malware samples collected.', array['Security', 'Networking', 'Data']::text[], 'ongoing', 'https://github.com/', null, null, array['Kabir Singh']::text[], false, 3),
  ('b0000000-0000-4000-8000-000000000004', 'ISSA Web Platform', 'This website: events, ticketing, live quizzes, submissions and an AI assistant, built on Next.js and Supabase.', 'Role-based access control enforced in Postgres, realtime quiz hosting and CSV/JSON exports for the core team.', array['Web', 'Open Source']::text[], 'ongoing', 'https://github.com/', '/', null, array['Rohan Iyer', 'Ananya Rao']::text[], true, 4),
  ('b0000000-0000-4000-8000-000000000005', 'LogLens', 'SIEM-lite dashboard that parses auth logs and alerts on brute-force and impossible-travel logins.', 'Streams syslog into DuckDB, runs detection rules written in SQL and pushes alerts to Discord.', array['Security', 'Data', 'Web']::text[], 'completed', 'https://github.com/', null, null, array['Diya Sharma', 'Meera Joshi']::text[], false, 5),
  ('b0000000-0000-4000-8000-000000000006', 'SecureVault', 'Educational zero-knowledge password manager demonstrating client-side encryption done right.', 'Argon2id key derivation, AES-GCM vault encryption and a threat model document written for first-year students.', array['Cryptography', 'Web']::text[], 'completed', 'https://github.com/', null, null, array['Aarav Mehta']::text[], false, 6),
  ('b0000000-0000-4000-8000-000000000007', 'DeepCheck', 'Research prototype that detects AI-generated profile photos in campus social platforms.', 'Fine-tuned vision transformer with frequency-domain features. Evaluated on a dataset collected with consent at ISSA events.', array['AI/ML', 'Research']::text[], 'ongoing', 'https://github.com/', null, null, array['Vikram Nair', 'Ananya Rao']::text[], false, 7)
