  ('c0000000-0000-4000-8000-000000000003', 'Security+ Study Group', '12 ISSA members', 'certification', 'Certified', 'Members cleared CompTIA Security+ after the club''s 10-week study programme.', (current_date - 60), null, null, false),
  ('c0000000-0000-4000-8000-000000000004', 'Best Paper Award — Student Research Symposium', 'Vikram Nair, Ananya Rao', 'publication', 'Best Paper', '“Detecting synthetic profile images with frequency-domain cues” (DeepCheck).', (current_date - 40), null, null, true),
  ('c0000000-0000-4000-8000-000000000005', 'Open-source Summer Programme', 'Rohan Iyer', 'award', 'Contributor', 'Selected to contribute to a major web security scanner over the summer.', (current_date - 120), null, null, false),
