insert into public.learning_resources (id, title, description, url, track, kind, level, is_free, source, tags, sort_order, is_featured) values
  ('a1000000-0000-4000-8000-000000000001', 'Cyber Security Roadmap', 'A visual, step-by-step map of what to learn first and what comes next.', 'https://roadmap.sh/cyber-security', 'Getting Started', 'roadmap', 'beginner', true, 'roadmap.sh', array['roadmap', 'career']::text[], 1, true),
  ('a1000000-0000-4000-8000-000000000002', 'CS50''s Introduction to Cybersecurity', 'Harvard''s free course on securing accounts, data, systems and software — no prerequisites.', 'https://cs50.harvard.edu/cybersecurity/', 'Getting Started', 'course', 'beginner', true, 'Harvard CS50', array['fundamentals']::text[], 2, true),
  ('a1000000-0000-4000-8000-000000000003', 'Linux Journey', 'Learn the Linux command line, permissions, processes and networking basics.', 'https://linuxjourney.com/', 'Linux & Networking', 'course', 'beginner', true, 'Linux Journey', array['linux', 'shell']::text[], 3, false),
  ('a1000000-0000-4000-8000-000000000004', 'OverTheWire: Bandit', 'A wargame that teaches the shell through 30+ small puzzles. The classic first CTF.', 'https://overthewire.org/wargames/bandit/', 'Linux & Networking', 'platform', 'beginner', true, 'OverTheWire', array['ctf', 'linux']::text[], 4, true),
  ('a1000000-0000-4000-8000-000000000005', 'Web Security Academy', 'Free interactive labs covering SQL injection, XSS, CSRF, SSRF and much more.', 'https://portswigger.net/web-security', 'Web Security', 'platform', 'intermediate', true, 'PortSwigger', array['web', 'labs', 'burp']::text[], 5, true),
  ('a1000000-0000-4000-8000-000000000006', 'OWASP Top 10', 'The industry reference for the most critical web application security risks.', 'https://owasp.org/www-project-top-ten/', 'Web Security', 'article', 'beginner', true, 'OWASP', array['web', 'owasp']::text[], 6, false),
  ('a1000000-0000-4000-8000-000000000007', 'MDN Web Docs', 'The best reference for HTML, CSS, JavaScript and how the web actually works.', 'https://developer.mozilla.org/', 'Web Development', 'notes', 'beginner', true, 'Mozilla', array['web', 'javascript']::text[], 7, false),
  ('a1000000-0000-4000-8000-000000000008', 'freeCodeCamp', 'Project-based certifications in web development, Python and more.', 'https://www.freecodecamp.org/', 'Web Development', 'course', 'beginner', true, 'freeCodeCamp', array['web', 'python']::text[], 8, false),
  ('a1000000-0000-4000-8000-000000000009', 'picoCTF', 'Beginner-friendly capture-the-flag practice with hints, run by Carnegie Mellon.', 'https://picoctf.org/', 'CTF Practice', 'platform', 'beginner', true, 'Carnegie Mellon University', array['ctf']::text[], 9, false),
  ('a1000000-0000-4000-8000-000000000010', 'TryHackMe', 'Guided, browser-based hacking rooms from complete beginner to advanced.', 'https://tryhackme.com/', 'CTF Practice', 'platform', 'beginner', false, 'TryHackMe', array['ctf', 'labs']::text[], 10, false),
  ('a1000000-0000-4000-8000-000000000011', 'Hack The Box Academy', 'Structured modules on penetration testing, from fundamentals to advanced.', 'https://academy.hackthebox.com/', 'CTF Practice', 'platform', 'intermediate', false, 'Hack The Box', array['pentest', 'labs']::text[], 11, false),
  ('a1000000-0000-4000-8000-000000000012', 'CyberChef', 'The "cyber Swiss army knife" for encoding, decoding, hashing and data analysis.', 'https://gchq.github.io/CyberChef/', 'Tools', 'tool', 'beginner', true, 'GCHQ', array['crypto', 'forensics']::text[], 12, false)
insert into public.quiz_questions (id, quiz_id, position, prompt, options, time_limit, points, explanation) values
  ('00010001-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 0, 'Which TCP port does HTTPS use by default?', array['80', '443', '8080', '22']::text[], 20, 1000, 'HTTPS is HTTP over TLS, served on TCP port 443 by default.'),
  ('00010002-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 1, 'Which attack tricks a logged-in user''s browser into sending an unwanted request to a trusted site?', array['XSS', 'CSRF', 'SSRF', 'Clickjacking']::text[], 20, 1000, 'Cross-Site Request Forgery rides on the victim''s existing session. Anti-CSRF tokens and SameSite cookies defend against it.'),
  ('00010003-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 2, 'Which of these is a hash function rather than an encryption algorithm?', array['AES', 'RSA', 'SHA-256', 'ChaCha20']::text[], 20, 1000, 'SHA-256 is a one-way hash. AES and ChaCha20 are symmetric ciphers; RSA is asymmetric.'),
  ('00010004-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 3, 'In the CIA triad, what does the “I” stand for?', array['Identity', 'Integrity', 'Isolation', 'Inspection']::text[], 15, 1000, 'Confidentiality, Integrity, Availability.'),
  ('00010005-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 4, 'Which tool is best known for network port scanning?', array['Wireshark', 'Nmap', 'Burp Suite', 'John the Ripper']::text[], 15, 1000, 'Nmap discovers hosts and services. Wireshark captures packets, Burp proxies web traffic, John cracks passwords.'),
  ('00010006-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 5, 'What does adding a unique salt to each password hash defend against?', array['Network sniffing', 'Precomputed rainbow-table attacks', 'Phishing', 'Keyloggers']::text[], 20, 1000, 'Salts make precomputed tables useless and ensure identical passwords hash differently.'),
  ('00010007-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 6, 'Which HTTP response header restricts where scripts can load from, helping mitigate XSS?', array['Content-Security-Policy', 'X-Powered-By', 'Accept-Encoding', 'ETag']::text[], 20, 1000, 'A strict Content-Security-Policy blocks inline and untrusted scripts.'),
  ('00010008-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000001', 7, 'Which Linux command changes a file''s permission bits?', array['chown', 'chmod', 'chgrp', 'umask']::text[], 15, 1000, 'chmod changes mode bits; chown changes ownership.'),
  ('00020001-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000002', 0, 'Phishing emails most commonly try to…', array['Steal credentials or deliver malware', 'Speed up your inbox', 'Update your operating system', 'Encrypt your files for safekeeping']::text[], 20, 1000, 'Phishing lures you into revealing credentials or running malware.'),
  ('00020002-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000002', 1, 'Which of these passwords is strongest?', array['P@ssw0rd', 'correct-horse-battery-staple-42', '12345678', 'qwerty!']::text[], 20, 1000, 'Length beats complexity: a long passphrase has far more entropy than a short “complex” password.'),
  ('00020003-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000002', 2, 'What does multi-factor authentication add to a login?', array['A second factor such as an OTP or security key', 'A longer password', 'A CAPTCHA', 'A VPN connection']::text[], 20, 1000, 'MFA requires something you have or are in addition to something you know.'),
  ('00020004-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000002', 3, 'Which protocol should replace Telnet for remote administration?', array['FTP', 'SSH', 'SNMP', 'HTTP']::text[], 15, 1000, 'SSH encrypts the session; Telnet sends everything, including passwords, in plaintext.'),
  ('00020005-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000002', 4, 'A “zero-day” vulnerability is…', array['A bug fixed on the day it was found', 'A flaw with no patch available because the vendor has had zero days to fix it', 'A virus that deletes itself after a day', 'An expired TLS certificate']::text[], 20, 1000, 'Zero-days are exploited before a fix exists.'),
  ('00020006-0000-4000-8000-000000000000', 'f0000000-0000-4000-8000-000000000002', 5, 'What is the primary job of a firewall?', array['Filter network traffic based on rules', 'Speed up internet access', 'Store passwords securely', 'Scan email attachments']::text[], 15, 1000, 'Firewalls allow or block traffic according to a rule set.')
